@startuml
abstract class Article {
  +String DOI
  +String title
  +type: enum {PeerReviewed, TechnicalReport}
}

class PeerReviewedArticle {
  +int citationCount
  +List<Person> reviewers
}

class TechnicalReport {
  +Institution institution
}

class Person {
  +String personID
  +String phone
  +String keywords
  +Institution institution
}

class Institution {
  +String code
  +String name
}

class Journal {
  +String name
  +double impactFactor
  +Publisher publisher
}

class Publisher {
  +String name
  +List<Journal> journals
}

' Associations

' Person - Institution (worksFor)
Person "0..*" -- Institution "1" : "worksFor"
Institution "1" -- Person "0..*" : "employs"

' Person - Article (author)
Person "0..*" -- Article "0..*" : "author"

' Article - PeerReviewedArticle (subclasses)
Article <|-- PeerReviewedArticle
Article <|-- TechnicalReport

' PeerReviewedArticle - Journal (publishedIn)
PeerReviewedArticle "1" -- Journal "0..*" : "publishedIn"

' Journal - Publisher (publishedBy)
Journal "1" -- Publisher "0..*" : "publishedBy"

' TechnicalReport - Institution (publishedBy)
TechnicalReport "1" -- Institution "0..*" : "publishedBy"

' Person - PeerReviewedArticle (reviewer)
Person "0..*" -- PeerReviewedArticle "0..*" : "reviewer"

@enduml

